module div_8bit(
    input clk,
    input rst,
    input sign,
    input [7:0] dividend,
    input [7:0] divisor,
    input opn_valid,
    input res_ready,
    output reg res_valid,
    output reg [15:0] result
);

    reg [8:0] SR;
    reg [3:0] cnt;
    reg [7:0] dividend_abs;
    reg [8:0] divisor_extend;
    reg [8:0] NEG_DIVISOR;
    reg [9:0] all_sub_result;
    reg [8:0] sub_result;
    reg [8:0] sub_remainer_reg_divisor;
    reg [7:0] REMAINER;
    reg [7:0] QUOTIENT;
    reg CO;
    reg [8:0] mux_result;
    reg [6:0] quotient_shift;
    reg [8:0] SR_final_update;
    reg [8:0] SR_shifting;
    reg [7:0] final_remainer;
    reg [7:0] final_quotient;
    reg is_final_quotient_sign;

    always @(*) begin
        divisor_extend = (sign && divisor[7]) ? {1'b1, divisor} : {1'b0, divisor};
        NEG_DIVISOR = (sign && divisor[7]) ? ~divisor_extend + 1 : divisor_extend;
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            res_valid <= 1'b0;
            SR <= 16'h0001;
            cnt <= 4'b0000;
        end
        else if (opn_valid && !res_valid) begin
            dividend_abs = (sign && dividend[7]) ? ~dividend + 1 : dividend;
            SR <= {dividend_abs, 1'b0};
            cnt <= 4'b0001;
        end
        else if (cnt == 4'b1000) begin
            SR <= SR_final_update;
            cnt <= 4'b0000;
        end
        else if (res_ready) begin
            SR <= SR_shifting;
            cnt <= cnt + 1;
        end
    end

    always @(*) begin
        all_sub_result = {REMAINER, SR[6:0]} + NEG_DIVISOR;
        sub_result = all_sub_result[8:0];
        sub_remainer_reg_divisor = all_sub_result;
        REMAINER = sub_remainer_reg_divisor[7:0];
        QUOTIENT = SR[7:0];
        CO = all_sub_result[9];
        mux_result = (CO) ? sub_result : REMAINER;
        quotient_shift = {SR[6:0], CO};
        SR_final_update = (cnt == 4'b1000) ? {REMAINER, SR[6:0]} : {mux_result, quotient_shift};
        SR_shifting = {SR[7:0], 1'b0};

        final_remainer = (sign && dividend[7] && divisor[7]) ? ~REMAINER + 1 : REMAINER;
        final_quotient = (sign && (dividend[7] ^ divisor[7])) ? ~QUOTIENT + 1 : QUOTIENT;
        is_final_quotient_sign = sign && (dividend[7] ^ divisor[7]);

        res_valid = (cnt == 4'b1000) ? 1'b1 : 1'b0;
        result = {final_remainer, final_quotient};
    end

endmodule
